final class LocalFirstLogoutTests {
 @Test void realAuthenticationClosesLocallyBeforeDiscoverySaveAndProviderForm()throws Exception{try(LogoutFixture f=new LogoutFixture()){var browser=f.login();assertTrue(f.live(browser));f.clock.now.set(LogoutFixture.NOW.plusSeconds(61));f.events.clear();var reply=f.application(LocalFirstLogout.Delivery.FORM_POST).handle(f.start(browser));assertEquals(200,reply.status());assertFalse(f.live(browser));assertEquals(1,f.closes.get());assertEquals(1,f.saves.get());assertEquals(0,f.logoutPosts.get());assertTrue(f.events.indexOf("close-detached")<f.events.indexOf("discovery"));assertTrue(f.events.indexOf("discovery")<f.events.indexOf("save"));String body=body(reply);assertTrue(body.contains("name=\"id_token_hint\""));assertTrue(body.contains(browser.authentication().getIdToken().toCompactSerialization()));assertFalse(body.contains("<script"));assertFalse(reply.toString().contains("eyJ"));assertEquals("no-store",reply.headers().get("Cache-Control"));assertEquals("no-referrer",reply.headers().get("Referrer-Policy"));assertTrue(reply.headers().get("Content-Security-Policy").startsWith("default-src 'none'"));assertClear(reply,LocalFirstLogout.SESSION_COOKIE);assertTrue(reply.cookies().stream().allMatch(c->c.contains("; Secure; HttpOnly; SameSite=Lax;")&&!c.contains("Domain=")));}}
 @Test void unknownEndpointAndDiscoveryOutageCannotUndoLocalClose()throws Exception{for(String mode:List.of("unsupported","outage"))try(LogoutFixture f=new LogoutFixture()){var browser=f.login();f.clock.now.set(LogoutFixture.NOW.plusSeconds(61));f.allowEndpoint=!mode.equals("unsupported");f.discoveryStatus=mode.equals("outage")?503:200;f.events.clear();var reply=f.application(LocalFirstLogout.Delivery.FORM_POST).handle(f.start(browser));assertEquals(503,reply.status());assertFalse(f.live(browser));assertEquals(0,f.saves.get());assertTrue(f.events.indexOf("close-detached")<f.events.indexOf("discovery"));assertTrue(body(reply).startsWith("Local session closed;"));assertClear(reply,LocalFirstLogout.SESSION_COOKIE);noCredential(reply,browser);}}
 @Test void deniedCsrfAndUnknownSessionNeverCloseSaveOrDiscover()throws Exception{try(LogoutFixture f=new LogoutFixture()){var browser=f.login();var app=f.application(LocalFirstLogout.Delivery.FORM_POST);int discovery=f.discovery.get();for(String field:List.of("csrf","session")){var headers=new LinkedHashMap<>(f.start(browser).headers());if(field.equals("csrf"))headers.put("x-csrf-token",List.of(other(browser.csrf())));else headers.put("cookie",List.of(LocalFirstLogout.SESSION_COOKIE+'='+other(browser.session())));var reply=app.handle(request(f.start(browser),headers));assertEquals(403,reply.status());assertTrue(reply.cookies().isEmpty());assertTrue(f.live(browser));}assertEquals(2,f.closes.get());assertEquals(0,f.saves.get());assertEquals(discovery,f.discovery.get());}}
 @Test void possiblyEffectfulCloseFailuresNeverRetryRollbackOrClaimConfirmedAuthorization()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);for(String mode:List.of("throw-before","throw-after","unavailable-before","unavailable-after","late","interrupt")){var browser=f.login();f.closeMode.set(mode);int closes=f.closes.get(),saves=f.saves.get(),discovery=f.discovery.get();try{var reply=app.handle(f.start(browser));assertEquals(503,reply.status());assertEquals(closes+1,f.closes.get());assertEquals(saves,f.saves.get());assertEquals(discovery,f.discovery.get());assertEquals(mode.endsWith("before"),f.live(browser));assertClear(reply,LocalFirstLogout.SESSION_COOKIE);assertClear(reply,LocalFirstLogout.PENDING_COOKIE);noCredential(reply,browser);assertEquals(mode.equals("late")||mode.equals("interrupt"),body(reply).startsWith("Local session closed;"));if(mode.equals("interrupt"))assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();f.nanoOffset.set(0);f.closeMode.set("normal");}}}}
 @Test void allNonSavedAndPossiblySavedOutcomesWithholdBrowserCredentials()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);for(String mode:List.of("UNAVAILABLE","CAPACITY_REFUSED","ALREADY_PRESENT","INDETERMINATE","throw-before","throw-after","null","late","interrupt")){var browser=f.login();f.saveMode.set(mode);int saves=f.saves.get();try{var reply=app.handle(f.start(browser));assertEquals(503,reply.status());assertFalse(f.live(browser));assertEquals(saves+1,f.saves.get());assertEquals(0,f.consumes.get());assertClear(reply,LocalFirstLogout.SESSION_COOKIE);assertClear(reply,LocalFirstLogout.PENDING_COOKIE);noCredential(reply,browser);if(mode.equals("interrupt"))assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();f.nanoOffset.set(0);f.saveMode.set("normal");}}}}
 @Test void callbackCorrelatesOnlyAndClearsOnlyItsBindingNotANewerSession()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);var browser=f.login();var prepared=app.handle(f.start(browser));String state=state(prepared),binding=binding(prepared);var newer=f.login();int tokens=f.tokenPosts.get(),discovery=f.discovery.get(),closes=f.closes.get();var callback=callback("state="+state,binding,newer.session());var reply=app.handle(callback);assertEquals(200,reply.status());assertTrue(body(reply).startsWith("Provider return correlated;"));assertClear(reply,LocalFirstLogout.PENDING_COOKIE);assertFalse(reply.cookies().stream().anyMatch(c->c.startsWith(LocalFirstLogout.SESSION_COOKIE+'=')));assertTrue(f.live(newer));assertFalse(f.live(browser));assertEquals(closes,f.closes.get());assertEquals(tokens,f.tokenPosts.get());assertEquals(discovery,f.discovery.get());assertEquals(0,f.logoutPosts.get());assertEquals(400,app.handle(callback).status());assertTrue(f.live(newer));}}
 @Test void actualAtomicPendingStoreAllowsOneConcurrentReturn()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);var browser=f.login();var prepared=app.handle(f.start(browser));var callback=callback("state="+state(prepared),binding(prepared),null);var pool=Executors.newFixedThreadPool(8);CountDownLatch start=new CountDownLatch(1);try{List<Future<LocalFirstLogout.Reply>> results=new ArrayList<>();for(int i=0;i<16;i++)results.add(pool.submit(()->{start.await();return app.handle(callback);}));start.countDown();int wins=0;for(var future:results){var reply=future.get(10,TimeUnit.SECONDS);assertClear(reply,LocalFirstLogout.PENDING_COOKIE);if(reply.status()==200)wins++;else assertTrue(reply.status()==400||reply.status()==503,"bounded admission may refuse without consume");}assertEquals(1,wins);}finally{start.countDown();pool.shutdownNow();assertTrue(pool.awaitTermination(3,TimeUnit.SECONDS));}}}
 @Test void malformedAndEncodedAliasReturnsNeverConsumeAndAlwaysClearPending()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);var browser=f.login();var prepared=app.handle(f.start(browser));String state=state(prepared),binding=binding(prepared);for(String malformed:List.of("","x","A".repeat(42),"A".repeat(44),"A".repeat(42)+"B")){var denied=app.handle(callback("state="+state,malformed,null));assertEquals(400,denied.status());assertClear(denied,LocalFirstLogout.PENDING_COOKIE);assertEquals(0,f.consumes.get());}for(String query:List.of("","state=","state=x","%73tate="+state,"state="+state+"&state="+state,"state="+state+"&code=x","state="+state+"&error=x","state="+state+"&iss=x","state=%C0%AF","state=%ED%A0%80","state="+state+"=","state="+state+";")){var reply=app.handle(callback(query,binding,null));assertEquals(400,reply.status());assertClear(reply,LocalFirstLogout.PENDING_COOKIE);assertEquals(0,f.consumes.get());}var reused=app.handle(callback("state="+state,binding,null));assertEquals(400,reused.status());assertClear(reused,LocalFirstLogout.PENDING_COOKIE);assertEquals(0,f.consumes.get());var fresh=f.login();var freshPrepared=app.handle(f.start(fresh));String freshState=state(freshPrepared),freshBinding=binding(freshPrepared);String encoded="state=%"+Integer.toHexString(freshState.charAt(0))+freshState.substring(1);var accepted=app.handle(callback(encoded,freshBinding,null));assertEquals(200,accepted.status());assertClear(accepted,LocalFirstLogout.PENDING_COOKIE);assertEquals(1,f.consumes.get());}}
 @Test void callbackStoreAcknowledgementLossAndLateOutputNeverRetryOrRecreateSession()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);for(String mode:List.of("throw-before","throw-after","null","late","interrupt")){var browser=f.login();var prepared=app.handle(f.start(browser));f.consumeMode.set(mode);int calls=f.consumes.get();try{var reply=app.handle(callback("state="+state(prepared),binding(prepared),null));assertEquals(503,reply.status());assertClear(reply,LocalFirstLogout.PENDING_COOKIE);assertFalse(reply.cookies().stream().anyMatch(c->c.startsWith(LocalFirstLogout.SESSION_COOKIE+'=')));assertFalse(f.live(browser));assertEquals(calls+1,f.consumes.get());if(mode.equals("interrupt"))assertTrue(Thread.currentThread().isInterrupted());}finally{Thread.interrupted();f.nanoOffset.set(0);f.consumeMode.set("normal");}}}}
 @Test void exactPendingExpiryAndWrongBrowserBindingCannotReturnCorrelation()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);var browser=f.login();var prepared=app.handle(f.start(browser));String state=state(prepared),binding=binding(prepared);assertEquals(400,app.handle(callback("state="+state,other(binding),null)).status());f.clock.now.set(LogoutFixture.NOW.plusSeconds(300));assertEquals(400,app.handle(callback("state="+state,binding,null)).status());assertFalse(f.live(browser));}}
 @Test void headerAndCookieMultiplicityArePreservedBeforeLocalEffect()throws Exception{try(LogoutFixture f=new LogoutFixture()){var browser=f.login();var app=f.application(LocalFirstLogout.Delivery.FORM_POST);var start=f.start(browser);List<Map<String,List<String>>> invalid=new ArrayList<>();for(String header:List.of("host","origin","x-csrf-token")){var values=new LinkedHashMap<>(start.headers());values.put(header,List.of(start.headers().get(header).get(0),start.headers().get(header).get(0)));invalid.add(values);}var split=new LinkedHashMap<>(start.headers());split.put("Cookie",List.of(LocalFirstLogout.SESSION_COOKIE+'='+browser.session()));invalid.add(split);var duplicate=new LinkedHashMap<>(start.headers());duplicate.put("cookie",List.of(LocalFirstLogout.SESSION_COOKIE+'='+browser.session()+"; "+LocalFirstLogout.SESSION_COOKIE+'='+browser.session()));invalid.add(duplicate);for(var headers:invalid){var reply=app.handle(request(start,headers));assertTrue(reply.status()==400||reply.status()==403);assertTrue(reply.cookies().isEmpty());assertTrue(f.live(browser));}for(String value:List.of("","x","A".repeat(42),"A".repeat(44),"A".repeat(42)+"B")){var malformed=new LinkedHashMap<>(start.headers());malformed.put("cookie",List.of(LocalFirstLogout.SESSION_COOKIE+'='+value));assertEquals(403,app.handle(request(start,malformed)).status());assertTrue(f.live(browser));}assertEquals(0,f.closes.get());assertEquals(0,f.saves.get());}}
 @Test void exactOriginHostMethodBodyAndQueryPolicyRejectBeforeTrustedClose()throws Exception{try(LogoutFixture f=new LogoutFixture()){var browser=f.login();var app=f.application(LocalFirstLogout.Delivery.FORM_POST);var base=f.start(browser);List<LocalFirstLogout.Request> invalid=new ArrayList<>();for(String origin:List.of("null","https://attacker.example",LogoutFixture.ORIGIN+"/","https://APP.example")){var headers=new LinkedHashMap<>(base.headers());headers.put("origin",List.of(origin));invalid.add(request(base,headers));}for(String host:List.of("attacker.example","app.example, app.example")){var headers=new LinkedHashMap<>(base.headers());headers.put("host",List.of(host));invalid.add(request(base,headers));}var authorization=new LinkedHashMap<>(base.headers());authorization.put("authorization",List.of("Bearer TEST-ONLY-token"));invalid.add(request(base,authorization));for(String query:List.of("","x=1"))invalid.add(LogoutFixture.request("POST","/logout",query,base.headers(),new byte[0],false,true));invalid.add(LogoutFixture.request("GET","/logout",null,base.headers(),new byte[0],false,true));invalid.add(LogoutFixture.request("POST","/logout",null,base.headers(),new byte[]{1},false,true));invalid.add(LogoutFixture.request("POST","/logout",null,base.headers(),new byte[0],true,true));invalid.add(LogoutFixture.request("POST","/logout",null,base.headers(),new byte[0],false,false));for(var request:invalid){assertTrue(app.handle(request).status()>=400);assertTrue(f.live(browser));}assertEquals(0,f.closes.get());assertEquals(0,f.saves.get());}}
 @Test void defaultFormEscapesSelectedUnicodeAndMarkupClientIdWithoutScript()throws Exception{try(LogoutFixture f=new LogoutFixture("client\"<&🙂","")){var browser=f.login();var reply=f.application(LocalFirstLogout.Delivery.FORM_POST).handle(f.start(browser));assertEquals(200,reply.status());String html=body(reply);assertTrue(html.contains("client&quot;&lt;&amp;&#x1f642;"));assertFalse(html.contains("client\"<"));assertFalse(html.contains("<script"));assertEquals(0,f.logoutPosts.get());}}
 @Test void trustedGetDeliveryHasBoundedLocationAndRefusesLargeCredentialWithoutSaving()throws Exception{try(LogoutFixture f=new LogoutFixture()){var browser=f.login();var reply=f.application(LocalFirstLogout.Delivery.GET_REDIRECT).handle(f.start(browser));assertEquals(303,reply.status());String location=Objects.requireNonNull(reply.headers().get("Location"));assertTrue(location.length()<=4096);assertTrue(location.contains("id_token_hint="));assertEquals(0,reply.body().length);assertFalse(f.live(browser));}try(LogoutFixture f=new LogoutFixture("logout-rp","x".repeat(6000))){var browser=f.login();var reply=f.application(LocalFirstLogout.Delivery.GET_REDIRECT).handle(f.start(browser));assertEquals(503,reply.status());assertFalse(f.live(browser));assertEquals(0,f.saves.get());noCredential(reply,browser);}}
 @Test void carrierRejectionAlwaysClearsOnlyCallbackPendingState()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);for(int status:List.of(400,413,503)){var reply=app.rejectCarrierRequest("/logout/callback",status);assertEquals(status,reply.status());assertClear(reply,LocalFirstLogout.PENDING_COOKIE);assertEquals(1,reply.cookies().size());assertTrue(app.rejectCarrierRequest("/logout",status).cookies().isEmpty());}assertThrows(IllegalArgumentException.class,()->app.rejectCarrierRequest("/logout",302));}}
 @Test void boundedRequestAndReplySnapshotsNeverRetainCallerMutableArraysOrLists()throws Exception{assertEquals(LocalFirstLogout.Delivery.FORM_POST,new LocalFirstLogout.Configuration(LogoutFixture.ORIGIN).delivery());try(LogoutFixture f=new LogoutFixture()){var browser=f.login();var start=f.start(browser);List<String> origins=new ArrayList<>(List.of(LogoutFixture.ORIGIN.toString()));Map<String,List<String>> headers=new LinkedHashMap<>(start.headers());headers.put("origin",origins);byte[] bytes={1};var request=LogoutFixture.request("POST","/logout",null,headers,bytes,false,true);origins.set(0,"https://attacker.example");bytes[0]=2;assertTrue(request.headers().get("origin").equals(List.of(LogoutFixture.ORIGIN.toString())));assertEquals(1,request.body()[0]);request.body()[0]=3;assertEquals(1,request.body()[0]);assertThrows(UnsupportedOperationException.class,()->request.headers().put("x",List.of("x")));assertThrows(IllegalArgumentException.class,()->LogoutFixture.request("POST","/logout",null,headers,new byte[4097],false,true));assertThrows(IllegalArgumentException.class,()->LogoutFixture.request("GET","/logout/callback","x".repeat(4097),headers,new byte[0],false,true));assertThrows(IllegalArgumentException.class,()->LogoutFixture.request("POST","/logout",null,Map.of("x".repeat(65),List.of("x")),new byte[0],false,true));var reply=f.application(LocalFirstLogout.Delivery.FORM_POST).handle(start);byte[] copy=reply.body();Arrays.fill(copy,(byte)0);assertTrue(body(reply).startsWith("<!doctype html>"));assertFalse(request.toString().contains(browser.csrf()));assertFalse(reply.toString().contains(browser.session()));}}
 @Test void ownedBindingDrawIsWipedOnSuccessAndProviderFailuresAfterLocalClose()throws Exception{try(LogoutFixture f=new LogoutFixture()){RecordingRandom random=new RecordingRandom();var app=new LocalFirstLogout(new LocalFirstLogout.Configuration(LogoutFixture.ORIGIN,LocalFirstLogout.Delivery.FORM_POST),f.client,f.pending,f::closeAuthorized,random,System::nanoTime);for(boolean fail:List.of(false,true)){var browser=f.login();random.fail=fail;var reply=app.handle(f.start(browser));assertEquals(fail?503:200,reply.status());assertFalse(f.live(browser));assertNotNull(random.retained);for(byte value:Objects.requireNonNull(random.retained))assertEquals(0,value);if(fail)noCredential(reply,browser);}}}
 @Test void eightEnteredSavesRefuseNinthBeforeCloseThenReleaseWithoutRetry()throws Exception{try(LogoutFixture f=new LogoutFixture()){var app=f.application(LocalFirstLogout.Delivery.FORM_POST);List<LogoutFixture.Browser> browsers=new ArrayList<>();for(int i=0;i<9;i++)browsers.add(f.login());f.control("block-save");var pool=Executors.newFixedThreadPool(8);List<Future<LocalFirstLogout.Reply>> results=new ArrayList<>();try{for(int i=0;i<8;i++){var browser=browsers.get(i);results.add(pool.submit(()->app.handle(f.start(browser))));}long until=System.nanoTime()+Duration.ofSeconds(2).toNanos();while(f.blockedEntered()!=8&&until-System.nanoTime()>0)Thread.sleep(1);assertEquals(8,f.blockedEntered(),"eight entered save callbacks");int closes=f.closes.get();var ninth=app.handle(f.start(browsers.get(8)));assertEquals(503,ninth.status());assertTrue(ninth.cookies().isEmpty());assertTrue(f.live(browsers.get(8)));assertEquals(closes,f.closes.get());f.control("release");for(var result:results)assertEquals(200,result.get(5,TimeUnit.SECONDS).status());assertEquals(8,f.saves.get());assertEquals(8,f.closes.get());}finally{f.control("release");pool.shutdownNow();assertTrue(pool.awaitTermination(3,TimeUnit.SECONDS));}}}

 @TestFactory @NonNull Stream<@NonNull DynamicTest> checkedCloseInterruptRemainsSetWithoutRetryRollbackOrAuthorizationClaim(){return Stream.of("checked-interrupt","checked-io-interrupt","checked-timeout").map(mode->DynamicTest.dynamicTest(mode,()->{try(LogoutFixture f=new LogoutFixture()){var browser=f.login();f.closeMode.set(mode);try{var reply=f.application(LocalFirstLogout.Delivery.FORM_POST).handle(f.start(browser));assertEquals(503,reply.status());assertFalse(f.live(browser));assertEquals(1,f.closes.get());assertEquals(0,f.saves.get());assertTrue(body(reply).startsWith("The local sign-out outcome is unavailable."));assertClear(reply,LocalFirstLogout.SESSION_COOKIE);noCredential(reply,browser);assertEquals(!mode.equals("checked-timeout"),Thread.currentThread().isInterrupted(),"checked interruption remains set; socket timeout does not invent interruption");}finally{Thread.interrupted();}}}));}

 private static LocalFirstLogout.@NonNull Request request(LocalFirstLogout.@NonNull Request original,@NonNull Map<@NonNull String,@NonNull List<@NonNull String>> headers){return LogoutFixture.request(original.method(),original.path(),original.rawQuery(),headers,original.body(),original.discarded(),original.trustedHttps());}
 private static LocalFirstLogout.@NonNull Request callback(@Nullable String query,@NonNull String binding,@Nullable String session){return LogoutFixture.request("GET","/logout/callback",query,Map.of("Host",List.of(LogoutFixture.ORIGIN.getRawAuthority()),"Cookie",List.of(LocalFirstLogout.PENDING_COOKIE+'='+binding+(session==null?"":"; "+LocalFirstLogout.SESSION_COOKIE+'='+session))),new byte[0],false,true);}
 private static @NonNull String body(LocalFirstLogout.@NonNull Reply reply){return new String(reply.body(),StandardCharsets.US_ASCII);}
 private static @NonNull String state(LocalFirstLogout.@NonNull Reply reply){var matcher=Pattern.compile("name=\"state\" value=\"([A-Za-z0-9_-]{43})\"").matcher(body(reply));assertTrue(matcher.find(),"prepared state field");return matcher.group(1);}
 private static @NonNull String binding(LocalFirstLogout.@NonNull Reply reply){return reply.cookies().stream().filter(c->c.startsWith(LocalFirstLogout.PENDING_COOKIE+'=')&&!c.contains("Max-Age=0")).map(c->c.substring(c.indexOf('=')+1,c.indexOf(';'))).findFirst().orElseThrow();}
 private static @NonNull String other(@NonNull String value){return (value.charAt(0)=='A'?"B":"A")+value.substring(1);}
 private static void assertClear(LocalFirstLogout.@NonNull Reply reply,@NonNull String name){assertTrue(reply.cookies().stream().anyMatch(c->c.startsWith(name+"=;")&&c.contains("Max-Age=0")),"selected cookie cleared");}
 private static void noCredential(LocalFirstLogout.@NonNull Reply reply,LogoutFixture.@NonNull Browser browser){assertFalse(reply.headers().containsKey("Location"));assertFalse(body(reply).contains(browser.authentication().getIdToken().toCompactSerialization()),"fixed failure contains no credential");assertFalse(body(reply).contains(browser.csrf()));assertFalse(body(reply).contains("TEST-ONLY-"));}
 private static final class RecordingRandom extends SecureRandom {private static final long serialVersionUID=1L;private final @NonNull SecureRandom delegate=new SecureRandom();byte @Nullable [] retained;boolean fail;@Override public void nextBytes(byte @NonNull [] bytes){this.retained=bytes;this.delegate.nextBytes(bytes);if(this.fail)throw new AssertionError("TEST-ONLY-provider-failure");}}
}
